// ═══ WITHOUT checked wrapper — CCE at GET (hard to debug) ═══
List<String> names = new ArrayList<>();
List rawRef = names;           // raw reference — bypasses generics!
rawRef.add(42);                // Integer sneaks in! No error!
String s = names.get(0);      // ClassCastException HERE! Far from the bug.

// ═══ WITH checked wrapper — CCE at ADD (easy to debug) ═══
List<String> checked = Collections.checkedList(new ArrayList<>(), String.class);
List rawRef2 = checked;        // raw reference
// rawRef2.add(42);            // ClassCastException immediately at ADD!
// Stack trace points to THIS line — easy to find the bug!

checked.add("Rajesh");         // (Recommended) String passes type check
// checked.add(42);            // (Avoid) ClassCastException at add()!

// ═══ checkedMap and checkedSet ═══
Map<String, Integer> checkedMap = Collections.checkedMap(
    new HashMap<>(), String.class, Integer.class);
// Every put() checks: key instanceof String AND value instanceof Integer

Set<String> checkedSet = Collections.checkedSet(new HashSet<>(), String.class);
// Every add() checks: element instanceof String
