package com.bank.checked;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class CheckedCollectionTest {

    @Test
    @SuppressWarnings({"unchecked", "rawtypes"})
    void unchecked_cceAtGetTime() {
        List<String> list = new ArrayList<>();
        List raw = list;
        raw.add(42);  // sneaks in!
        assertThatThrownBy(() -> { String s = list.get(0); })
            .isInstanceOf(ClassCastException.class);
    }

    @Test
    @SuppressWarnings({"unchecked", "rawtypes"})
    void checked_cceAtAddTime() {
        List<String> checked = Collections.checkedList(new ArrayList<>(), String.class);
        List raw = checked;
        assertThatThrownBy(() -> raw.add(42))
            .isInstanceOf(ClassCastException.class);
        // CCE at ADD! Stack trace shows exactly where the bug is!
    }

    @Test
    void checked_allowsCorrectType() {
        List<String> checked = Collections.checkedList(new ArrayList<>(), String.class);
        checked.add("SAV2001");
        checked.add("CUR3001");
        assertThat(checked).containsExactly("SAV2001", "CUR3001");
    }

    @Test
    @SuppressWarnings({"unchecked", "rawtypes"})
    void checkedMap_enforcesTypes() {
        Map<String, Integer> checked = Collections.checkedMap(
            new HashMap<>(), String.class, Integer.class);
        checked.put("SAV2001", 75000);  // (Recommended) 
        Map raw = checked;
        assertThatThrownBy(() -> raw.put("SAV2001", "not-a-number"))
            .isInstanceOf(ClassCastException.class);
    }
}
